export interface ClaudeMascotProps {
  variant?: 'walking' | 'gym' | 'flag' | 'confetti' | 'random';
}

export function ClaudeMascot({ variant = 'flag' }: ClaudeMascotProps) {
  const [actualVariant, setActualVariant] = React.useState<'walking' | 'gym' | 'flag' | 'confetti'>(
    variant === 'random' ? 'flag' : variant as any
  );

  useEffect(() => {
    if (variant === 'random') {
      const variants = ['walking', 'gym', 'flag', 'confetti'] as const;
      setActualVariant(variants[Math.floor(Math.random() * variants.length)]);
    } else {
      setActualVariant(variant as any);
    }
  }, [variant]);

  switch (actualVariant) {
    case 'walking': return <WalkingMascot />;
    case 'gym': return <GymMascot />;
    case 'confetti': return <ConfettiMascot />;
    case 'flag':
    default:
      return <FlagMascot />;
  }
}
